using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests;

public static class TestHelper
{
    public static SchoolContext CreateContext(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        var context = new SchoolContext(options);
        return context;
    }

    public static SchoolContext CreateSeededContext(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var context = CreateContext(dbName);
        SeedBasicData(context);
        return context;
    }

    public static void SeedBasicData(SchoolContext context)
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01")
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        context.Courses.AddRange(
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 }
        );
        context.SaveChanges();

        context.Students.AddRange(
            new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
            new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
            new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") }
        );
        context.SaveChanges();

        var instructor = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11")
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();
    }

    /// <summary>
    /// Drains the static NotificationService queue to isolate tests.
    /// </summary>
    public static void DrainNotificationQueue()
    {
        var svc = new ContosoUniversity.Services.NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        TestHelper.DrainNotificationQueue();
        _context = TestHelper.CreateSeededContext();
        _controller = new StudentsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelper.DrainNotificationQueue();
    }

    // ---- Index ----

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.True(model.Count > 0);
        // Default sort is by LastName ascending
        var names = model.Select(s => s.LastName).ToList();
        Assert.Equal(names.OrderBy(n => n), names);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        var names = model.Select(s => s.LastName).ToList();
        Assert.Equal(names.OrderByDescending(n => n), names);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        var dates = model.Select(s => s.EnrollmentDate).ToList();
        Assert.Equal(dates.OrderBy(d => d), dates);
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        var dates = model.Select(s => s.EnrollmentDate).ToList();
        Assert.Equal(dates.OrderByDescending(d => d), dates);
    }

    [Fact]
    public void Index_SearchString_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Alexander", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersStudents()
    {
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    [Fact]
    public void Index_NewSearchString_ResetsPageTo1()
    {
        // When searchString is not null, page should be reset to 1
        var result = _controller.Index(null, "OldFilter", "NewSearch", 5) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_NullSearchString_UsesCurrentFilter()
    {
        // When searchString is null, it falls back to currentFilter
        var result = _controller.Index(null, "Alexander", null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SetsViewBagSortParameters()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm as string);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm as string);
    }

    [Fact]
    public void Index_WithNameDescSort_SetsNameSortParmToEmpty()
    {
        _controller.Index("name_desc", null, null, null);

        // When sortOrder is not empty, NameSortParm should be ""
        Assert.Equal("", _controller.ViewBag.NameSortParm as string);
    }

    [Fact]
    public void Index_WithDateSort_SetsDateSortParmToDateDesc()
