    // ---- File extension edge cases ----

    [Theory]
    [InlineData(".jpg", true)]
    [InlineData(".jpeg", true)]
    [InlineData(".png", true)]
    [InlineData(".gif", true)]
    [InlineData(".bmp", true)]
    [InlineData(".exe", false)]
    [InlineData(".pdf", false)]
    [InlineData(".txt", false)]
    public void Create_Post_ValidatesFileExtension(string extension, bool shouldPass)
    {
        var course = new Course { CourseID = 5555, Title = "Test", Credits = 3, DepartmentID = 1 };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns($"test{extension}");
        fileMock.Setup(f => f.Length).Returns(1000);

        // For valid extensions, the controller will try to write the file.
        // We set up a content root to temp path so it can proceed.
        if (shouldPass)
        {
            var stream = new MemoryStream(new byte[1000]);
            fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
        }

        var result = _controller.Create(course, fileMock.Object);

        if (shouldPass)
        {
            // Should either redirect (success) or return view with upload error (file system)
            // but NOT have the extension error
            if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
            {
                var errors = _controller.ModelState["teachingMaterialImage"].Errors;
                Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
            }
        }
        else
        {
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errorMsg = _controller.ModelState["teachingMaterialImage"].Errors[0].ErrorMessage;
            Assert.Contains("valid image file", errorMsg);
        }
    }
}

