    private void SeedInstructorData(SchoolContext context)
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000,
            StartDate = DateTime.Parse("2007-09-01")
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var instructor1 = new Instructor
        {
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = DateTime.Parse("1995-03-11")
        };
        var instructor2 = new Instructor
        {
            FirstMidName = "Fadi",
            LastName = "Fakhouri",
            HireDate = DateTime.Parse("2002-07-06")
        };
        context.Instructors.AddRange(instructor1, instructor2);
        context.SaveChanges();

        var course1 = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = 1 };
        var course2 = new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = 1 };
        context.Courses.AddRange(course1, course2);
        context.SaveChanges();

        context.CourseAssignments.Add(new CourseAssignment
        {
            InstructorID = instructor1.ID,
            CourseID = 1050
        });
        context.SaveChanges();

        context.OfficeAssignments.Add(new OfficeAssignment
        {
            InstructorID = instructor2.ID,
            Location = "Smith 17"
        });
        context.SaveChanges();

        // Add enrollment for course
        var student = new Student
        {
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = DateTime.Parse("2010-09-01")
        };
        context.Students.Add(student);
        context.SaveChanges();

        context.Enrollments.Add(new Enrollment
        {
            StudentID = student.ID,
            CourseID = 1050,
            Grade = Grade.A
        });
        context.SaveChanges();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        TestHelper.DrainNotificationQueue();
    }

    // ---- Index ----

    [Fact]
    public void Index_NoSelection_ReturnsViewWithInstructors()
    {
        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
        Assert.Null(model.Courses);
        Assert.Null(model.Enrollments);
    }

    [Fact]
    public void Index_WithInstructorSelected_ReturnsCourses()
    {
        var instructor = _context.Instructors.First(i => i.LastName == "Abercrombie");

        var result = _controller.Index(instructor.ID, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
        Assert.Equal("Chemistry", model.Courses.First().Title);
        Assert.Equal(instructor.ID, (int)_controller.ViewBag.InstructorID);
    }

