using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        // Drain static queue before each test
        DrainQueue();
        _service = new NotificationService();
    }

    public void Dispose()
    {
        _service.Dispose();
        DrainQueue();
    }

    private static void DrainQueue()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    // ---- SendNotification + ReceiveNotification ----

    [Fact]
    public void SendNotification_EnqueuesNotification_ReceiveDequeues()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("TestUser", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var result = _service.ReceiveNotification();

        Assert.Null(result);
    }

    [Fact]
    public void SendNotification_WithDisplayName_IncludesNameInMessage()
    {
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "TestUser");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("John Doe", notification.Message);
        Assert.Contains("Student", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Course", "42", EntityOperation.UPDATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("ID: 42", notification.Message);
        Assert.Contains("Course", notification.Message);
    }

    // ---- GenerateMessage via different operations ----

    [Fact]
    public void SendNotification_CreateOperation_MessageContainsCreated()
    {
        _service.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("created", notification.Message);
        Assert.Contains("Alice", notification.Message);
        Assert.StartsWith("New ", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateOperation_MessageContainsUpdated()
    {
        _service.SendNotification("Course", "2", "Physics", EntityOperation.UPDATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("updated", notification.Message);
        Assert.Contains("Physics", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteOperation_MessageContainsDeleted()
    {
        _service.SendNotification("Department", "3", "Math", EntityOperation.DELETE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("deleted", notification.Message);
        Assert.Contains("Math", notification.Message);
    }

    [Fact]
    public void SendNotification_CreateWithoutDisplayName_MessageFormat()
    {
        _service.SendNotification("Instructor", "5", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Instructor (ID: 5) has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_UpdateWithDisplayName_MessageFormat()
    {
        _service.SendNotification("Course", "10", "Advanced Math", EntityOperation.UPDATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Course 'Advanced Math' has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_DeleteWithDisplayName_MessageFormat()
    {
        _service.SendNotification("Student", "7", "Bob Smith", EntityOperation.DELETE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student 'Bob Smith' has been deleted", notification.Message);
    }

    // ---- Default userName ----

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_ExplicitUserName_UsesProvided()
    {
        _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Admin", notification.CreatedBy);
    }

    // ---- CreatedAt ----

    [Fact]
    public void SendNotification_SetsCreatedAtToApproximatelyNow()
    {
        var before = DateTime.Now.AddSeconds(-1);
        _service.SendNotification("Student", "1", EntityOperation.CREATE);
        var after = DateTime.Now.AddSeconds(1);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    // ---- FIFO order ----

    [Fact]
    public void Notifications_AreDequeuedInFIFOOrder()
    {
        _service.SendNotification("A", "1", EntityOperation.CREATE);
        _service.SendNotification("B", "2", EntityOperation.UPDATE);
        _service.SendNotification("C", "3", EntityOperation.DELETE);

        var n1 = _service.ReceiveNotification();
        var n2 = _service.ReceiveNotification();
        var n3 = _service.ReceiveNotification();

        Assert.Equal("A", n1.EntityType);
        Assert.Equal("B", n2.EntityType);
        Assert.Equal("C", n3.EntityType);
    }

    // ---- MarkAsRead is a no-op ----

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op, just verify it doesn't throw
        var exception = Record.Exception(() => _service.MarkAsRead(1));
        Assert.Null(exception);

        _service.MarkAsRead(0);
        _service.MarkAsRead(-1);
        _service.MarkAsRead(int.MaxValue);
    }

    // ---- Queue cap ----

    [Fact]
    public void SendNotification_QueueCap_DoesNotExceed500()
    {
        // Send 510 notifications to exceed the 500 cap
        for (int i = 0; i < 510; i++)
        {
            _service.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        // Drain the queue and count
        int count = 0;
        while (_service.ReceiveNotification() != null)
        {
            count++;
        }

        // Should be capped at or near 500 (best-effort trimming)
        Assert.True(count <= 500, $"Queue had {count} items, expected <= 500");
    }

    // ---- Dispose ----

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var svc = new NotificationService();
        var exception = Record.Exception(() => svc.Dispose());
        Assert.Null(exception);
    }

    // ---- Two-arg overload delegates to five-arg ----

    [Fact]
    public void SendNotification_TwoArgOverload_SetsNullDisplayName()
    {
        _service.SendNotification("Student", "99", EntityOperation.DELETE, "User1");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        // When display name is null, message uses ID format
        Assert.Contains("ID: 99", notification.Message);
        Assert.Equal("User1", notification.CreatedBy);
        Assert.Equal("DELETE", notification.Operation);
    }
}

using ContosoUniversity.Data;
