+using ContosoUniversity.Controllers;
+using ContosoUniversity.Data;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+using Microsoft.AspNetCore.Mvc;
+
+namespace ContosoUniversity.Tests.Controllers;
+
+public class NotificationsControllerTests : IDisposable
+{
+    private readonly SchoolContext _context;
+    private readonly NotificationsController _controller;
+
+    public NotificationsControllerTests()
+    {
+        TestHelper.DrainNotificationQueue();
+        _context = TestHelper.CreateContext();
+        _controller = new NotificationsController(_context);
+    }
+
+    public void Dispose()
+    {
+        _controller.Dispose();
+        _context.Dispose();
+        TestHelper.DrainNotificationQueue();
+    }
+
+    [Fact]
+    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
+    {
+        var result = _controller.GetNotifications();
+
+        Assert.NotNull(result);
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        Assert.NotNull(jsonResult.Value);
+
+        // Use reflection to inspect anonymous type
+        var value = jsonResult.Value;
+        var successProp = value.GetType().GetProperty("success");
+        var countProp = value.GetType().GetProperty("count");
+        Assert.True((bool)successProp.GetValue(value));
+        Assert.Equal(0, (int)countProp.GetValue(value));
+    }
+
+    [Fact]
+    public void GetNotifications_WithNotifications_ReturnsNotifications()
+    {
+        // Enqueue notifications via the notification service
+        var svc = new NotificationService();
+        svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "System");
+        svc.SendNotification("Course", "2", "Test Course", EntityOperation.UPDATE, "System");
+
+        var result = _controller.GetNotifications();
+
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        var value = jsonResult.Value;
+        var successProp = value.GetType().GetProperty("success");
+        var countProp = value.GetType().GetProperty("count");
+        var notifProp = value.GetType().GetProperty("notifications");
+        Assert.True((bool)successProp.GetValue(value));
+        Assert.Equal(2, (int)countProp.GetValue(value));
+        var notifications = (List<Notification>)notifProp.GetValue(value);
+        Assert.Equal(2, notifications.Count);
+        Assert.Equal("Student", notifications[0].EntityType);
+        Assert.Equal("Course", notifications[1].EntityType);
+    }
+
+    [Fact]
+    public void GetNotifications_LimitsTo10()
+    {
+        var svc = new NotificationService();
+        for (int i = 0; i < 15; i++)
+        {
+            svc.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE, "System");
+        }
+
+        var result = _controller.GetNotifications();
+
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        var value = jsonResult.Value;
+        var countProp = value.GetType().GetProperty("count");
+        Assert.Equal(10, (int)countProp.GetValue(value));
+    }
+
+    [Fact]
+    public void MarkAsRead_ReturnsSuccess()
+    {
+        var result = _controller.MarkAsRead(1);
+
+        var jsonResult = Assert.IsType<JsonResult>(result);
+        var value = jsonResult.Value;
+        var successProp = value.GetType().GetProperty("success");
+        Assert.True((bool)successProp.GetValue(value));
+    }
+
+    [Fact]
+    public void Index_ReturnsView()
+    {
+        var result = _controller.Index() as ViewResult;
+
+        Assert.NotNull(result);
+    }
+
+    [Fact]
+    public void GetNotifications_DequeuedNotificationsNotReturnedAgain()
+    {
+        var svc = new NotificationService();
+        svc.SendNotification("Student", "1", "Test", EntityOperation.CREATE, "System");
+
+        // First call dequeues
+        _controller.GetNotifications();
+
+        // Second call should be empty
+        var result2 = _controller.GetNotifications();
+        var jsonResult = Assert.IsType<JsonResult>(result2);
+        var value = jsonResult.Value;
+        var countProp = value.GetType().GetProperty("count");
+        Assert.Equal(0, (int)countProp.GetValue(value));
