+    {
+        var result = _controller.Index() as ViewResult;
+
+        Assert.NotNull(result);
+    }
+
+    [Fact]
+    public void About_ReturnsViewWithEnrollmentDateGroups()
+    {
+        var result = _controller.About() as ViewResult;
+
+        Assert.NotNull(result);
+        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
+        Assert.NotEmpty(model);
+
+        // We seeded 3 students with different enrollment dates (2010, 2012, 2013)
+        // so we should have distinct groups
+        Assert.True(model.Count >= 2);
+
+        // Each group should have a valid date and a positive count
+        foreach (var group in model)
+        {
+            Assert.NotNull(group.EnrollmentDate);
+            Assert.True(group.StudentCount > 0);
+        }
+    }
+
+    [Fact]
+    public void About_GroupsStudentsByEnrollmentDate()
+    {
+        // Add students with the same enrollment date to verify grouping
+        var sameDate = DateTime.Parse("2023-01-15");
+        _context.Students.AddRange(
+            new Student { FirstMidName = "A", LastName = "X", EnrollmentDate = sameDate },
+            new Student { FirstMidName = "B", LastName = "Y", EnrollmentDate = sameDate }
+        );
+        _context.SaveChanges();
+
+        var result = _controller.About() as ViewResult;
+
+        Assert.NotNull(result);
+        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
+        var group2023 = model.FirstOrDefault(g => g.EnrollmentDate == sameDate);
+        Assert.NotNull(group2023);
+        Assert.Equal(2, group2023.StudentCount);
+    }
+
+    [Fact]
+    public void About_EmptyDatabase_ReturnsEmptyList()
+    {
+        // Create controller with empty context
+        var emptyContext = TestHelper.CreateContext();
+        using var controller = new HomeController(emptyContext);
+
+        var result = controller.About() as ViewResult;
+
+        Assert.NotNull(result);
+        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
+        Assert.Empty(model);
+    }
+
+    [Fact]
