[Fact]
public void Create_Post_EnrollmentDateBefore1753_AddsModelError()
{
    var student = new Student
    {
        FirstMidName = "Test",
        LastName = "Student",
        EnrollmentDate = new DateTime(1752, 12, 31)
    };

    var result = _controller.Create(student) as ViewResult;

    Assert.NotNull(result);
    Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    var errors = _controller.ModelState["EnrollmentDate"].Errors;
    Assert.Contains(errors, e => e.ErrorMessage.Contains("1753"));
}

[Fact]
public void Create_Post_ValidBoundaryDate1753_Succeeds()
{
    var student = new Student
    {
        FirstMidName = "Boundary",
        LastName = "Test",
        EnrollmentDate = new DateTime(1753, 1, 1)
    };

    var result = _controller.Create(student);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
}

[Fact]
public void Create_Post_ValidStudent_SavesAllFields()
{
    var date = DateTime.Parse("2023-09-01");
    var student = new Student
    {
        FirstMidName = "Jane",
        LastName = "Doe",
        EnrollmentDate = date
    };

    _controller.Create(student);

    var saved = _context.Students.FirstOrDefault(s => s.LastName == "Doe");
    Assert.NotNull(saved);
    Assert.Equal("Jane", saved.FirstMidName);
    Assert.Equal("Doe", saved.LastName);
    Assert.Equal(date, saved.EnrollmentDate);
}

